// src/context/UserContext.jsx
import { createContext, useContext, useState, useEffect } from 'react';

export const UserContext = createContext();

export function UserProvider({ children }) {
  const [user, setUser] = useState(() => {
    const stored = localStorage.getItem('user');
    return stored ? JSON.parse(stored) : null;
  });

  useEffect(() => {
    if (user) {
      localStorage.setItem('user', JSON.stringify(user));
    } else {
      localStorage.removeItem('user');
    }
  }, [user]);

  const logout = () => {
    setUser(null);
    localStorage.removeItem('user');
    localStorage.removeItem('token');
  };

  return (
    <UserContext.Provider value={{ user, setUser, logout }}>
      {children}
    </UserContext.Provider>
  );
}

export const useUser = () => {
  const context = useContext(UserContext);
  if (!context) {
    throw new Error('useUser must be used within UserProvider');
  }
  return context;
};// src/App.jsx
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { UserProvider, useUser } from './context/UserContext';
import Navbar from './components/NavBar';
import Footer from './components/Footer';

import Login from './pages/Login';
import Register from './pages/Register';
import Home from './pages/Home';
import Movies from './pages/Movies';
import Series from './pages/Series';
import Anime from './pages/Anime';
import MediaDetails from './pages/MediaDetails';
import MediaRatedDetails from './pages/MediaRatedDetails'; // <-- 1. Importe o componente
import Lists from './pages/Lists';
import ListDetails from './pages/ListDetails';
import ListDetailsItem from './pages/ListDetailsItem';
import Profile from './pages/Profile';

function PrivateRoute({ children }) {
  const { user } = useUser();
  return user ? children : <Navigate to="/login" replace />;
}

function PublicRoute({ children }) {
  const { user } = useUser();
  return user ? <Navigate to="/home" replace /> : children;
}

function AppContent() {
  const { user } = useUser();

  return (
    <div className="flex flex-col min-h-screen">
      {user && <Navbar />}
      <main className="flex-1">
        <Routes>
          <Route path="/" element={<Navigate to="/login" replace />} />
          <Route
            path="/login"
            element={
              <PublicRoute>
                <Login />
              </PublicRoute>
            }
          />
          <Route
            path="/register"
            element={
              <PublicRoute>
                <Register />
              </PublicRoute>
            }
          />
          <Route
            path="/home"
            element={
              <PrivateRoute>
                <Home />
              </PrivateRoute>
            }
          />
          <Route
            path="/movies"
            element={
              <PrivateRoute>
                <Movies />
              </PrivateRoute>
            }
          />
          <Route
            path="/series"
            element={
              <PrivateRoute>
                <Series />
              </PrivateRoute>
            }
          />
          <Route
            path="/anime"
            element={
              <PrivateRoute>
                <Anime />
              </PrivateRoute>
            }
          />
          {/* Rota para ver detalhes de uma mídia (de qualquer lugar, exceto perfil) */}
          <Route
            path="/media/:id"
            element={
              <PrivateRoute>
                <MediaDetails />
              </PrivateRoute>
            }
          />
          {/* 2. ADICIONE A NOVA ROTA AQUI */}
          {/* Rota para ver/editar uma AVALIAÇÃO (acessada pelo Perfil) */}
          <Route
            path="/rated/:type/:id"
            element={
              <PrivateRoute>
                <MediaRatedDetails />
              </PrivateRoute>
            }
          />
          <Route
            path="/lists"
            element={
              <PrivateRoute>
                <Lists />
              </PrivateRoute>
            }
          />
          <Route
            path="/lists/:id"
            element={
              <PrivateRoute>
                <ListDetails />
              </PrivateRoute>
            }
          />
          <Route
            path="/lists/:listId/item/:id"
            element={
              <PrivateRoute>
                <ListDetailsItem />
              </PrivateRoute>
            }
          />
          <Route
            path="/profile"
            element={
              <PrivateRoute>
                <Profile />
              </PrivateRoute>
            }
          />
        </Routes>
      </main>
      {user && <Footer />}
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <UserProvider>
        <AppContent />
      </UserProvider>
    </BrowserRouter>
  );
}

export default App;// src/services/lists.js
import api from './api';

export const createList = async (payload) => {
  try {
    const response = await api.post('/media/listas/create', payload);
    return response.data;
  } catch (error) {
    console.error('Error creating list:', error);
    throw error;
  }
};

export const addItemToList = async (payload) => {
  try {
    const response = await api.post('/media/listas/item/add', payload);
    return response.data;
  } catch (error) {
    console.error('Error adding item to list:', error);
    throw error;
  }
};

export const removeItemFromList = async (payload) => {
  try {
    const response = await api.delete('/media/listas/item/delete', { data: payload });
    return response.data;
  } catch (error) {
    console.error('Error removing item from list:', error);
    throw error;
  }
};

export const getList = async (payload) => {
  try {
    const response = await api.post('/media/listas/get', payload);
    return response.data;
  } catch (error) {
    console.error('Error fetching list:', error);
    throw error;
  }
};

export const getUserLists = async (payload) => {
  try {
    const response = await api.post('/media/listas/user/get', payload);
    return response.data;
  } catch (error) {
    console.error('Error fetching user lists:', error);
    throw error;
  }
};

export const deleteList = async (payload) => {
  try {
    const response = await api.delete('/media/listas/delete', { data: payload });
    return response.data;
  } catch (error) {
    console.error('Error deleting list:', error);
    throw error;
  }
};

export const deleteListItem = async (payload) => {
  try {
    const response = await api.delete('/media/listas/item/delete', {
      data: payload,
    });
    return response.data; // Retorna a mensagem de sucesso do backend
  } catch (error) {
    // Re-lança o erro para que o componente que chamou a função possa tratá-lo
    throw error;
  }
